INSERT INTO internal.pipeline_actions (operation, definition) VALUES
  ('set_agent_action_policy', '{"operation":"set_agent_action_policy","rpc":"set_agent_action_policy","label":"Set what agents may do","description":"Sets one action to `auto` (runs straight away), `ask` (waits for a person) or `never`, for everyone, one role or one service credential; `default` removes the setting. Signing, submitting for review, amending, locking and deleting are always Never, and changes to agent permissions can never be Auto. Needs AI settings access. With a token or in a pipeline it can only tighten; to loosen, ask with `request_agent_action` and a person approves it in the app. Returns the setting. Sends `agent.policy.changed`.","arguments":[{"name":"p_workspace_id","type":"uuid","required":true,"nullable":false},{"name":"p_action_key","type":"text","required":true,"nullable":false},{"name":"p_level","type":"text","required":true,"nullable":false},{"name":"p_subject_kind","type":"text","required":false,"nullable":false},{"name":"p_role","type":"text","required":false,"nullable":true},{"name":"p_credential_id","type":"uuid","required":false,"nullable":true}]}'::jsonb),
  ('set_agent_definition_enabled', '{"operation":"set_agent_definition_enabled","rpc":"set_agent_definition_enabled","label":"Switch an agent on or off","description":"Switches one of the agents on the Agents page on or off. Its owner, an admin or a steward can. With a token or in a pipeline it can only tighten; to loosen, ask with `request_agent_action` and a person approves it in the app. Returns the agent. Sends `agent.enabled` or `agent.disabled`.","arguments":[{"name":"p_definition_id","type":"uuid","required":true,"nullable":false},{"name":"p_enabled","type":"boolean","required":true,"nullable":false}]}'::jsonb),
  ('disable_agent_operation_policy', '{"operation":"disable_agent_operation_policy","rpc":"disable_agent_operation_policy","label":"Turn off an agent operation policy","description":"Stops one service credential running one kind of draft on its own. From then on its drafts wait for a person. Needs a workspace admin or steward; works from a personal token or a pipeline too, since it only tightens. Turning one on needs a signature in the app. Returns the policy. Sends `agent.operation_policy.disabled`.","arguments":[{"name":"p_workspace_id","type":"uuid","required":true,"nullable":false},{"name":"p_policy_id","type":"uuid","required":true,"nullable":false}]}'::jsonb),
  ('request_agent_action', '{"operation":"request_agent_action","rpc":"request_agent_action","label":"Ask a person to approve an agent action","description":"Records an action for a person to approve, such as giving agents more room. What happens next depends on the setting for that action: refused (Never), waiting for a person (Ask) or ready to run (Auto). Changes to agent permissions always wait for someone who manages the AI settings.","arguments":[{"name":"p_workspace_id","type":"uuid","required":true,"nullable":false,"server":"workspace"},{"name":"p_action_key","type":"text","required":true,"nullable":false},{"name":"p_arguments","type":"jsonb","required":true,"nullable":false},{"name":"p_summary","type":"text","required":true,"nullable":false},{"name":"p_provenance","type":"jsonb","required":true,"nullable":false},{"name":"p_idempotency_key","type":"text","required":true,"nullable":false,"server":"idempotency"}]}'::jsonb),
  ('set_lab_watcher', '{"operation":"set_lab_watcher","rpc":"set_lab_watcher","label":"Turn a lab watcher on or off","description":"Sets a watcher: its kind, whether it is on, how often it looks, an optional project and its settings. Returns the watcher.","arguments":[{"name":"p_workspace_id","type":"uuid","required":true,"nullable":false},{"name":"p_kind","type":"text","required":true,"nullable":false},{"name":"p_enabled","type":"boolean","required":true,"nullable":false},{"name":"p_schedule","type":"text","required":false,"nullable":false},{"name":"p_project_id","type":"uuid","required":false,"nullable":true},{"name":"p_params","type":"jsonb","required":false,"nullable":false}]}'::jsonb),
  ('run_lab_watcher', '{"operation":"run_lab_watcher","rpc":"run_lab_watcher","label":"Run a lab watcher now","description":"Looks straight away instead of waiting for the schedule. Returns how many new findings were made.","arguments":[{"name":"p_watcher_id","type":"uuid","required":true,"nullable":false}]}'::jsonb),
  ('set_watcher_finding_status', '{"operation":"set_watcher_finding_status","rpc":"set_watcher_finding_status","label":"Dismiss or snooze a watcher finding","description":"`dismiss`, `snooze` (with a time in the future) or `reopen`. Returns the finding.","arguments":[{"name":"p_finding_id","type":"uuid","required":true,"nullable":false},{"name":"p_action","type":"text","required":true,"nullable":false},{"name":"p_until","type":"timestamptz","required":false,"nullable":false}]}'::jsonb)
INSERT INTO internal.pipeline_trigger_events (name) VALUES
  ('agent.enabled'),
  ('agent.disabled'),
  ('agent.operation_policy.disabled'),
  ('agent.operation_policy.created'),
  ('agent.signed_policy.changed'),
  ('agent.proposal.created'),
  ('agent.proposal.updated'),
  ('agent.workflow.created'),
  ('agent.workflow.updated')
